import './gta-email-recovery-runtime.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');
const dir='artifacts/opportunity-sweep-20261016';await fs.mkdir(dir,{recursive:true});
const names=['Tailored Rooms Home Staging','Quality Home Staging','AURA Contracting','MVP Condo Management','REZA PEYVANDI','SIM UPPAL','RACHEL NG','Apple Self Storage Chatham — Business contact','ALFRED CHUI'];
const old=JSON.parse(await fs.readFile('artifacts/partner-sales-audit-20261016/contacts.json'));const out=[];
for(const name of names){const c0=old.find(c=>c.name===name);if(!c0)throw Error('Missing '+name);const[c]=await db('market_contacts',{id:'eq.'+c0.id});const[thread,tasks,leads]=await Promise.all([db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.asc,id.asc',limit:'1000'}),db('crm_tasks',{related_id:'eq.'+c.id}),db('crm_leads',{or:`(data->>phone.eq.${c.phone},data->>phone.eq.${c.phone?.replace(/^\+1/,'')},data->>partnerReferralContactId.eq.${c.id},data->>relationshipContactId.eq.${c.id})`})]);if(thread.length===1000)throw Error('Pagination required');const details=[];for(const l of leads){const logs=await db('crm_followup_logs',{'data->>leadId':'eq.'+l.id,order:'updated_at.desc',limit:'15'});details.push({lead:l,logs});}out.push({contact:c,thread,tasks,sales:details});}
await fs.writeFile(dir+'/review.json',JSON.stringify({at:new Date().toISOString(),rows:out},null,2));
for(const r of out)console.log(JSON.stringify({name:r.contact.name,id:r.contact.id,phone:r.contact.phone,suppressed:r.contact.do_not_contact||r.contact.cross_channel_suppressed_at,notes:r.contact.notes,tasks:r.tasks.map(t=>({id:t.id,title:t.title,status:t.status,description:t.description})),sales:r.sales.map(s=>({id:s.lead.id,deleted:s.lead.deleted,name:s.lead.data.name,stage:s.lead.data.stage,move:s.lead.data.moveDate,notes:s.lead.data.notes,summary:s.lead.data.partnerLeadSummary,last:s.logs.slice(0,3).map(l=>l.data.notes)})),thread:r.thread.map(t=>({id:t.id,d:t.direction,at:t.created_at,text:t.notes}))}));
